  for (const { categoria, socio } of prestamos) {
    if (!grupos.has(categoria)) grupos.set(categoria, new Set());
    grupos.get(categoria).add(socio);
  }
  return [...grupos].map(([categoria, socios]) => [categoria, socios.size]);
}
